mkdir -p /tmp/marked-repro && cd /tmp/marked-repro && npm init -y >/dev/null 2>&1 && npm install marked@latest --silent && node --input-type=module <<'EOF'
import { marked } from "marked";

const escape = (text) =>
  text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const FOLLOWABLE = /^(https?:|mailto:|#|\/)/i;

marked.use({
  gfm: true,
  renderer: {
    html: ({ text }) => escape(text),
    link({ href, title, tokens }) {
      const text = this.parser.parseInline(tokens);
      if (!FOLLOWABLE.test(href)) return text;
      const label = title ? ` title="${escape(title)}"` : "";
      return `<a href="${escape(href)}"${label} target="_blank" rel="noreferrer">${text}</a>`;
    },
  },
});

const samples = [
  `[x](https://example.com 'a" onmouseover="alert(1)')`,
  `[x](https://example.com "a\\" onmouseover=\\"alert(1)")`,
  `[x](https://example.com/"onmouseover="alert(1))`,
  `[x](<https://example.com/"onmouseover="alert(1)>)`,
  `[x](javascript:alert(1))`,
  `[x](https://example.com)`,
];
for (const sample of samples) {
  console.log("IN ", sample);
  console.log("OUT", marked.parse(sample, { async: false }).trim());
  console.log("---");
}
console.log("marked", (await import("marked/package.json", { with: { type: "json" } })).default.version);
EOF

