import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const bundle = new URL("./tools/icons/bundle.ts", import.meta.url);
const iconsDirectory = fileURLToPath(new URL("../../client/static/icons/", bundle));
const sample = path.join(iconsDirectory, "sprite-v66.svg");
const fromRoot = path.resolve("..", "static", "icons");
const fromToolsIcons = path.resolve("tools", "static", "icons");
console.log(JSON.stringify({
  iconsDirectory,
  sampleExists: existsSync(sample),
  directoryExists: existsSync(iconsDirectory),
  missesRootRelative: fromRoot !== iconsDirectory,
  missesToolsRelative: fromToolsIcons !== iconsDirectory
}, null, 2));

function stepUp(selectedIndex, length) {
  selectedIndex = Math.max(selectedIndex - 1, -1);
  if (selectedIndex === -1) {
    const count = length ?? 0;
    selectedIndex = count > 0 ? count - 1 : -1;
  }
  return selectedIndex;
}
function select(item) {
  let notified = false;
  let hidden = false;
  let error = null;
  try {
    if (item) {
      const host = (value) => {
        if (typeof value?.id !== "string") return;
        notified = value.id;
      };
      host(item);
    }
    hidden = true;
  } catch (e) {
    error = e.message;
  }
  return { notified, hidden, error };
}
const results = [{ id: "a" }, { id: "b" }, { id: "c" }];
const wrapped = stepUp(0, results.length);
const missing = select(results[results.length]);
const chosen = select(results[wrapped]);
const none = select(results[-1]);
console.log(JSON.stringify({ wrapped, missing, chosen, none, empty: stepUp(0, 0) }));
EOF

python3 << 'PY'
import os
roots = ["client", "shared", "services", "schema", "tools", "apps", "extensions", "deployment"]
skip = {".git", "node_modules", "dist", "build", ".turbo", ".svelte-kit", "coverage", ".wrangler", ".plasmo", "artifacts", "vendor"}
candidates = []
for root in roots:
    if not os.path.isdir(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root, topdown=False):
        dirnames[:] = [d for d in dirnames if d not in skip and not d.startswith(".")]
        parts = set(dirpath.split(os.sep))
        if parts & skip:
            continue
        visible = [f for f in filenames if f != ".DS_Store"]
        subdirs = [d for d in os.listdir(dirpath) if os.path.isdir(os.path.join(dirpath, d)) and d not in skip and not d.startswith(".")]
        if visible:
            continue
        # empty, or only empty/leftover children we already classified
        only_empty_children = all(
            os.path.join(dirpath, d) in {c[0] for c in candidates} or not any(os.scandir(os.path.join(dirpath, d)))
            for d in subdirs
        )
        if not visible and (not subdirs or only_empty_children):
            candidates.append((dirpath, subdirs))
for path, subs in candidates:
    print(f"{path}" + (f"  [{', '.join(subs)}]" if subs else ""))
PY
